#!/usr/bin/env bash\nset -euo pipefail\necho "🔨 Build..."\nmvn -q clean package -DskipTests\necho "🐳 Docker compose..."\ndocker compose up -d --build\necho "⏳ Esperando health..."\nfor i in {1..45}; do\n  if curl -sf http://localhost:8080/actuator/health > /dev/null 2>&1; then\n    echo ""\n    echo "✅ App UP"\n    curl -s http://localhost:8080/actuator/health | head -c 500\n    echo ""\n    echo ""\n    echo "Camunda REST/UI: no expuesto; el motor se invoca desde el backend."\n    echo "Health:    http://localhost:8080/actuator/health"\n    echo "Métricas:  http://localhost:8080/actuator/metrics"\n    exit 0\n  fi\n  sleep 2\ndone\necho "❌ Timeout. Logs:"\ndocker compose logs app --tail 200\nexit 1